export const PAYOUTS={'Fishing Contest':['rods',1],'Raft Race':['raft',1],'Treasure Hunt':['pickaxes',1],'Cozy Farm':['fertilizer',2],'Zobo Shooter':['zobo',200]};
export const LABELS={rods:'🎣 Fishing Rods',raft:'🛶 Rafts',pickaxes:'⛏️ Iron Pickaxes',fertilizer:'🌾 Magic Fertilizer',zobo:'🎯 Bullet Coins',energy_drinks:'🥤 Energy Drinks',pinballs:'🔵 Pinballs earned',candy:'🍬 Candy',catch_tatari:'🐾 Catch Tatari',blue_card_packs:'🔵 Blue Card Packs',boost_x2_minutes:'✨ ×2 Boost (min)'};
export const UNLOCKS={1:0,2:0,3:240,5:360,10:600,20:1200,40:2400,60:4800,100:7200,150:7200,200:7200};
const PROBS={party:.251,event:.22,gold_candy:.22,jackpot:.017,card_hole:.033,unmodelled:.004};
export const unlocked=amount=>Object.entries(UNLOCKS).filter(([,n])=>amount>=n).map(([m])=>Number(m));
export function seed(value){let n=2166136261;for(const c of String(value)){n^=c.charCodeAt(0);n=Math.imul(n,16777619)}return n>>>0}
export class RNG{constructor(s){this.state=s>>>0;this.nextNormal=null}random(){let t=this.state+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296}normal(){if(this.nextNormal!==null){const z=this.nextNormal;this.nextNormal=null;return z}const r=Math.sqrt(-2*Math.log(1-this.random())),a=2*Math.PI*this.random();this.nextNormal=r*Math.sin(a);return r*Math.cos(a)}gamma(shape,scale=1){if(shape<1)return this.gamma(shape+1,scale)*Math.pow(1-this.random(),1/shape);const d=shape-1/3,c=1/Math.sqrt(9*d);while(true){const x=this.normal(),v0=1+c*x;if(v0<=0)continue;const v=v0*v0*v0,u=1-this.random();if(u<1-.0331*x*x*x*x||Math.log(u)<.5*x*x+d*(1-v+Math.log(v)))return scale*d*v}}beta(a,b){const x=this.gamma(a),y=this.gamma(b);return x/(x+y)}}
export function binomial(rng,n,p){if(n<=0||p<=0)return 0;if(p>=1)return n;if(p>.5)return n-binomial(rng,n,1-p);let total=0;while(n>48&&n*p>8){const a=1+Math.floor(n/2),beta=rng.beta(a,n+1-a);if(beta>=p){n=a-1;p/=beta}else{total+=a;n-=a;p=(p-beta)/(1-beta)}}if(n*p<=8){let position=0;const log=Math.log1p(-p);while(true){position+=1+Math.floor(Math.log1p(-rng.random())/log);if(position>n)return total;total++}}for(let i=0;i<n;i++)if(rng.random()<p)total++;return total}
export function poisson(rng,mean){let total=0;while(mean>10){const n=Math.max(1,Math.floor(mean*.875)),arrival=rng.gamma(n);if(arrival>mean)return total+binomial(rng,n-1,mean/arrival);total+=n;mean-=arrival}let threshold=Math.exp(-mean),product=1,k=0;while(product>threshold){product*=rng.random();k++}return total+Math.max(0,k-1)}
export function outcomes(rng,rolls,targetOnly=false){let remaining=rolls,mass=1,result={};for(const key of targetOnly?['party','event']:Object.keys(PROBS)){const count=binomial(rng,remaining,PROBS[key]/mass);result[key]=count;remaining-=count;mass-=PROBS[key]}return result}
export function session(rng,amount,event,multiplier,refire,rows,gold=true,candy=null,targetOnly=false){const [resource,payout]=PAYOUTS[event];let pool=amount,progression=0,collected=0,spent=0,earned=0,jackpot=0,card_hole=0,unmodelled=0,machine={},party={};while(pool>=multiplier){const rolls=Math.floor(pool/multiplier),cost=rolls*multiplier;pool-=cost;spent+=cost;const hits=outcomes(rng,rolls,targetOnly);progression+=hits.party*4*multiplier;machine[resource]=(machine[resource]||0)+hits.event*payout*multiplier;if(!targetOnly){if(gold)machine.energy_drinks=(machine.energy_drinks||0)+hits.gold_candy*multiplier;else if(candy!==null)machine.candy=(machine.candy||0)+hits.gold_candy*candy*multiplier;jackpot+=hits.jackpot;card_hole+=hits.card_hole;unmodelled+=hits.unmodelled}let returned=0;while(collected<rows.length&&progression>=rows[collected].total_cost){for(let [key,value]of Object.entries(rows[collected].rewards)){if(key==='event')key=resource;party[key]=(party[key]||0)+value;if(key==='pinballs'){returned+=value;earned+=value}}collected++}pool+=returned;if(!refire)break}let haul={};for(const key of new Set([...Object.keys(machine),...Object.keys(party)]))haul[key]=(machine[key]||0)+(party[key]||0);return{haul,machine,party,progression,jackpot,card_hole,unmodelled,earned,spent,milestones:collected,remaining:pool,refired:Math.max(0,spent-Math.floor(amount/multiplier)*multiplier)}}
export function quantiles(values){const sorted=values.slice().sort((a,b)=>a-b),q=p=>sorted[Math.max(0,Math.ceil(p*sorted.length)-1)];return{low:q(.125),high:q(.875),low50:q(.25),high50:q(.75),median:q(.5),mean:values.reduce((a,b)=>a+b,0)/values.length}}
function table(data,event,gold){const rows=data.tables[event]?.[gold?'gold_active':'gold_inactive'];if(!rows?.length)throw Error('This event’s Party table is missing.');return rows}
export function forward(amount,event,gold,multiplier,refire,data,samples=10000){if(!PAYOUTS[event]||!Number.isInteger(amount)||amount<1||amount>10000000||!unlocked(amount).includes(multiplier))throw Error('Enter 1–10,000,000 Pinballs and an unlocked multiplier.');const rng=new RNG(seed(JSON.stringify([data,amount,event,gold,multiplier,refire,samples]))),rows=table(data,event,gold),records=[];for(let i=0;i<samples;i++)records.push(session(rng,amount,event,multiplier,refire,rows,gold,data.direct_candy_per_x1));let result={samples,haul:{},machine:{},party:{}};for(const section of ['haul','machine','party']){const keys=new Set(records.flatMap(r=>Object.keys(r[section])));for(const key of keys)result[section][key]=quantiles(records.map(r=>r[section][key]||0))}for(const key of ['progression','jackpot','card_hole','unmodelled','earned','remaining','refired','milestones'])result[key]=quantiles(records.map(r=>r[key]));return result}
export function reverse(target,event,partyOn,data,samples=10000){if(!PAYOUTS[event]||!Number.isInteger(target)||target<1||target>10000000)throw Error('Enter a target from 1 to 10,000,000.');const [resource,payout]=PAYOUTS[event];if(!partyOn){const hits=Math.ceil(target/payout),rng=new RNG(seed(`off:${target}:${event}:${samples}`)),values=[];for(let i=0;i<samples;i++)values.push(hits+poisson(rng,rng.gamma(hits,(1-.22)/.22)));return{...quantiles(values),samples}}const rows=table(data,event,true),cache=new Map(),trialCount=2048,version=seed(JSON.stringify(data));function probability(amount){if(!cache.has(amount)){const rng=new RNG(seed(`${version}:${target}:${event}:${amount}`));let reached=0;for(let i=0;i<trialCount;i++)if((session(rng,amount,event,1,true,rows,true,null,true).haul[resource]||0)>=target)reached++;cache.set(amount,reached/trialCount)}return cache.get(amount)}let upper=Math.max(1,Math.ceil(target/(.22*payout)));while(probability(upper)<.875){if(upper>=80000000)throw Error('This target exceeds the solver range.');upper=Math.min(upper*2,80000000)}const estimates=[];for(const p of [.125,.5,.875]){let lo=0,hi=upper;while(hi-lo>Math.max(1,Math.floor(hi/1000))){const mid=Math.floor((lo+hi)/2);if(probability(mid)>=p)hi=mid;else lo=mid}estimates.push(hi)}estimates.sort((a,b)=>a-b);return{low:estimates[0],median:estimates[1],high:estimates[2],samples:trialCount,evaluations:cache.size}}
